using System.Text.Json;
using EqlTracker.Core;

static class DirectPetEditingTests
{
    public static void Register(Action<string, Action> test)
    {
        static void Check(bool value) { if (!value) throw new Exception("Direct pet editing assertion failed"); }
        static ItemDefinition Armor() => new() { Key = "armor", Name = "Armor", Slots = ["CHEST"], Classes = ["ALL"], MetadataComplete = true };
        static PetInventoryItem Entry(int position, string name) => new() { Id = name, Position = position, Name = name, ItemKey = name, Slot = "Storage", Rank = position };
        test("Pet quick add uses requested empty position without an equipped claim", () => { var b = new PetBuild(); Check(PetInventoryEditing.Add(b, Armor(), null, 7, 3, true, out var item, out _)); Check(item is { Position: 3, Rank: 0, Slot: "Storage", EquipmentVerified: false } && item.ConfirmedAt != null && item.Id.Length > 0); });
        test("Occupied pet drop uses first empty active position without replacing stock", () => { var b = new PetBuild { Items = [Entry(1, "old")] }; Check(PetInventoryEditing.Add(b, Armor(), null, 4, 1, false, out var item, out _)); Check(item!.Position == 2 && b.Items[0].Id == "old" && b.Items[0].Rank == 1); });
        test("Full pet inventory rejects add atomically", () => { var b = new PetBuild { Items = Enumerable.Range(1, 4).Select(p => Entry(p, "a" + p)).ToList() }; string before = JsonSerializer.Serialize(b); Check(!PetInventoryEditing.Add(b, Armor(), null, 4, 1, false, out _, out var error)); Check(error.Contains("full") && JsonSerializer.Serialize(b) == before); });
        test("Multiple chest items are valid inventory members", () => { var b = new PetBuild(); Check(PetInventoryEditing.Add(b, Armor(), null, 4, null, false, out _, out _)); Check(PetInventoryEditing.Add(b, Armor(), null, 4, null, false, out _, out _)); Check(b.Items.Count == 2 && b.Items.All(i => i.Slot == "Storage")); });
        test("Quick add copies physical rank and known effects without aliasing source", () => { var source = new InventoryEntry { Name = "Armor +5", Count = 1, Augments = [new() { Name = "Effect", EffectText = "Focus: known", EffectIdentity = "effect" }] }; var b = new PetBuild(); Check(PetInventoryEditing.Add(b, Armor(), source, 4, null, false, out var item, out _)); source.Augments.Clear(); Check(item!.Rank == 5 && item.Exaltations.Count == 1 && !item.EquipmentVerified); });
        test("Collection evidence supplies no physical rank or socketed effects", () => { var b = new PetBuild(); Check(PetInventoryEditing.Add(b, Armor(), new() { Name = "Armor +9", Location = "Equipment", Count = null }, 4, null, false, out var item, out _)); Check(item!.Rank == 0 && item.Exaltations.Count == 0); });
        test("Pet reorder shifts entries while configured effects remain in their positions", () => { var b = new PetBuild { Items = [Entry(1, "a"), Entry(2, "b"), Entry(3, "c")] }; b.Items[0].Exaltations.Add(new() { Effect = "Focus: one" }); Check(PetInventoryEditing.Reorder(b, "a", 3, out _)); Check(b.Items.Single(i => i.Id == "a").Position == 3 && b.Items.Single(i => i.Id == "b").Position == 1 && b.Items.Single(i => i.Id == "c").Position == 2 && b.Items.Single(i => i.Id == "a").Exaltations.Count == 0 && b.Items.Single(i => i.Id == "b").Exaltations.Count == 1 && b.SlotConfigurations.Single().Position == 1); });
        test("Pet reorder upward and into empty positions creates no collisions", () => { var b = new PetBuild { Items = [Entry(1, "a"), Entry(3, "b")] }; Check(PetInventoryEditing.Reorder(b, "b", 1, out _)); Check(b.Items.Single(i => i.Id == "a").Position == 2 && b.Items.Single(i => i.Id == "b").Position == 1); Check(PetInventoryEditing.Reorder(b, "a", 4, out _)); Check(b.Items.Select(i => i.Position).Distinct().Count() == 2); });
        test("Pet rank edit rejects invalid input and retains rank-locked slot intent", () => { var b = new PetBuild { Items = [Entry(1, "a")] }; b.Items[0].Rank = 4; b.Items[0].Exaltations.Add(new() { SourceName = "Proc source", Effect = "Proc: test" }); var c = new Catalog(); string before = JsonSerializer.Serialize(b); Check(!PetInventoryEditing.SetRank(b, "a", 21, c, out _) && JsonSerializer.Serialize(b)==before); Check(PetInventoryEditing.SetRank(b,"a",3,c,out _)); Check(b.Items[0].Rank==3 && b.SlotConfigurations.Single().Effects.Count==1); });
        test("Pet rank commit and undo retain effects and original identity", () => { var b = new PetBuild { Items = [Entry(1, "a")] }; Check(PetInventoryEditing.SetRank(b, "a", 20, new Catalog(), out _)); Check(b.Items[0].Rank == 20); Check(PetBuildEditing.Undo(b, out _)); Check(b.Items[0].Id == "a" && b.Items[0].Rank == 1); });
        test("Pet identity migration is stable across saved copies and repeated normalization", () => { var b = new PetBuild { Items = [new() { ItemKey = "x", Position = 1 }, new() { ItemKey = "x", Position = 2 }] }; PetInventoryEditing.EnsureIdentities(b); var copy = EquipmentPositions.Copy(b); PetInventoryEditing.EnsureIdentities(copy); Check(copy.Items.Select(i => i.Id).SequenceEqual(b.Items.Select(i => i.Id)) && copy.Items.Select(i => i.Id).Distinct().Count() == 2); });
        test("Class-capacity reductions retain inactive items while preventing new overflow", () => { var b = new PetBuild { Items = Enumerable.Range(1, 7).Select(p => Entry(p, "a" + p)).ToList() }; Check(!PetInventoryEditing.Add(b, Armor(), null, 4, null, false, out _, out _)); Check(b.Items.Count == 7); });
    }
}
